+    constexpr size_t UNROLL_FACTOR = 8;
+    const size_t remainder = n % UNROLL_FACTOR;
+    uint64_t sub_hist[UNROLL_FACTOR][256];
+
+    // Initialize sub-histograms (only needed for correctness if caller doesn't zero them,
+    // but the harness zeroes the main hist array, we must ensure sub_hist is clean)
+    for (size_t k = 0; k < UNROLL_FACTOR; ++k) {
+        for (int b = 0; b < 256; ++b) {
+            sub_hist[k][b] = 0;
+        }
+    }
+
+    size_t i = 0;
+    int64_t current_sum = 0;
+    while (i + UNROLL_FACTOR <= n) {
+        size_t idx = i % UNROLL_FACTOR;
+        uint64_t* current_sub = sub_hist[idx];
+      
+        for (size_t j = 0; j < UNROLL_FACTOR; ++j) {
+            size_t current_i = i + j;
+            int64_t val = in[current_i];
+          
+            // Update prefix sum
+            current_sum += val;
+            out[current_i] = current_sum;
+
+            // Update histogram using local/private counter
+            current_sub[val & 255]++;
+        }
+        i += UNROLL_FACTOR;
+    }
+
+    // Handle remainder
+    for (; i < n; ++i) {
+        current_sum += in[i];
+        out[i] = current_sum;
         hist[in[i] & 255]++;
+    }
+
+    // Sum up sub-histograms into the main histogram
+    for (size_t k = 0; k < UNROLL_FACTOR; ++k) {
+        for (int b = 0; b < 256; ++b) {
+            hist[b] += sub_hist[k][b];
+        }
     }
 }
